import 'dart:convert';
import 'package:flutter/widgets.dart';

/// Guess Number level-selection screen embedded as a PNG in Dart.
/// No separate image asset or pubspec.yaml entry is required.
class GuessNumberLevelsImage extends StatelessWidget {
  const GuessNumberLevelsImage({super.key});

  static const String _imageBase64 = '';

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      base64Decode(_imageBase64),
      fit: BoxFit.contain,
      width: double.infinity,
    );
  }
}
